create table if not exists public.group_join_requests (id uuid primary key default gen_random_uuid(), group_id uuid not null references public.chat_groups(id) on delete cascade, user_id uuid not null references public.profiles(id) on delete cascade, status text not null default 'pending' check(status in ('pending','approved','declined')), created_at timestamptz not null default now(), responded_at timestamptz, responded_by uuid references public.profiles(id) on delete set null); create unique index if not exists group_join_requests_one_pending_idx on public.group_join_requests(group_id,user_id) where status='pending'; create index if not exists group_join_requests_pending_idx on public.group_join_requests(group_id,status,created_at); alter table public.group_join_requests enable row level security; drop policy if exists "Group admins can read pending join requests" on public.group_join_requests; create policy "Group admins can read pending join requests" on public.group_join_requests for select to authenticated using (exists(select 1 from public.group_members gm where gm.group_id=group_join_requests.group_id and gm.user_id=(select auth.uid()) and gm.role in ('creator','admin')));
